
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_rmspbel_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_rmspbel", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.608434743882097e+00, -4.517746599163358e+00, -4.390716591211521e+00, -4.214846213120805e+00, -3.975410597035463e+00, -3.657198038678087e+00, -3.248637610670611e+00, -2.749237861537732e+00, -2.178626316869419e+00, -1.563700560795159e+00, -9.995164849066817e-01, -6.723974197485904e-01, -6.046727999188252e-01, -5.132800955500380e-01, -3.652938307739305e-01, -2.258563018772061e-01, -1.247324042091149e-01, -4.885301133891322e-02, -1.080451541591615e-02, -1.216191333017453e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


